# Fix the pattern function
def create_pattern_around_3(grid, center_r, center_c):
    c_r, c_c = center_r, center_c
    import copy
    grid = copy.deepcopy(grid)

    # Pattern: 5x5 square centered at (c_r, c_c), plus 2s on row c_r+2 outside the 5x5
    # Relative coordinates from top-left of 5x5:
    # Top row (rel=0): all 5s
    # Row c_r-1 (rel=1): [2, 0, 5, 0, 2]
    # Row c_r (rel=2): [2, 0, 3, 0, 2]
    # Row c_r+1 (rel=3): [2, 0, 0, 0, 2]
    # Row c_r+2 (rel=4): [8, 8, 8, 8, 8]

    for r in range(c_r - 2, c_r + 3):
        for c in range(c_c - 2, c_c + 3):
            rel_r, rel_c = r - (c_r - 2), c - (c_c - 2)

            if rel_r == 0:
                grid[r][c] = 5
            elif rel_r == 1:
                if rel_c == 2:
                    grid[r][c] = 5
                elif rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 2:
                if rel_c == 2:
                    grid[r][c] = 3
                elif rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 3:
                if rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 4:
                grid[r][c] = 8

    # Row c_r+2 also has 2s outside the 5x5 area
    row_base = [0] * len(grid[c_r + 2])
    for c in range(c_c - 2, c_c + 3):
        row_base[c] = 2  # 8-bar already set, 2s overlay inside? No wait
        pass
    # Actually the 8-bar is in cols c_c-2 to c_c+2, and 2s extend outside
    grid[c_r + 2] = [2] * len(grid[c_r + 2])

    return grid

