# The issue: row c_r+2 has 8s in cols c_c-2 to c_c+2, and 2s elsewhere
# But I was setting the whole row to 2s, overwriting the 8s

def create_pattern_around_3_fixed(grid, center_r, center_c):
    c_r, c_c = center_r, center_c
    import copy
    grid = copy.deepcopy(grid)

    # Build the 5x5 pattern with 5s, 2s, and 8s in row c_r+2
    for r in range(c_r - 2, c_r + 3):
        for c in range(c_c - 2, c_c + 3):
            rel_r, rel_c = r - (c_r - 2), c - (c_c - 2)

            if rel_r == 0:
                grid[r][c] = 5
            elif rel_r == 1:
                if rel_c == 2:
                    grid[r][c] = 5
                elif rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 2:
                if rel_c == 2:
                    grid[r][c] = 3
                elif rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 3:
                if rel_c in [0, 4]:
                    grid[r][c] = 2
                else:
                    grid[r][c] = 0
            elif rel_r == 4:
                grid[r][c] = 8

    # Add 2s for the rest of row c_r+2 (outside the 5x5 area)
    row_idx = c_r + 2
    for c in range(len(grid[row_idx])):
        if c < c_c - 2 or c > c_c + 2:
            grid[row_idx][c] = 2

    return grid

